-- ============================================================
-- ENRICHISSEMENT FORMATIONS 7-9
-- ============================================================

-- ============================================================
-- FORMATION 7 : Ressources Humaines et Gestion du Capital Humain
-- ============================================================
DO $$ DECLARE
  v_course_id uuid;
  v_mod5 uuid; v_mod6 uuid; v_mod7 uuid;
  v_max_pos int;
BEGIN
  SELECT id INTO v_course_id FROM courses WHERE slug = 'ressources-humaines-recruter-former-fideliser';
  SELECT COALESCE(MAX(position), 0) INTO v_max_pos FROM modules WHERE course_id = v_course_id;

  INSERT INTO modules (course_id, title, position) VALUES
    (v_course_id, 'Droit du Travail en Zone OHADA et UEMOA', v_max_pos + 1),
    (v_course_id, 'Rémunération, Avantages Sociaux et Motivation', v_max_pos + 2),
    (v_course_id, 'Digitalisation RH et SIRH pour PME Africaines', v_max_pos + 3);

  SELECT id INTO v_mod5 FROM modules WHERE course_id = v_course_id ORDER BY position OFFSET v_max_pos LIMIT 1;
  SELECT id INTO v_mod6 FROM modules WHERE course_id = v_course_id ORDER BY position OFFSET v_max_pos + 1 LIMIT 1;
  SELECT id INTO v_mod7 FROM modules WHERE course_id = v_course_id ORDER BY position OFFSET v_max_pos + 2 LIMIT 1;

  INSERT INTO lessons (module_id, course_id, title, type, position, is_free_preview, content) VALUES

  (v_mod5, v_course_id, 'Le contrat de travail en droit OHADA : types et clauses essentielles', 'document', 1, false,
   E'# Le Contrat de Travail en Droit OHADA\n\n## Le cadre juridique du travail en Afrique\nEn Afrique de l''Ouest, le droit du travail est régi par :\n- **Le Code du Travail national** (chaque pays a le sien)\n- **Les conventions collectives** sectorielles\n- **La jurisprudence** des tribunaux du travail\n- **Les normes OIT** (Organisation Internationale du Travail) ratifiées\n\n**Important :** Bien que les principes soient similaires, les détails varient selon les pays. Cette leçon présente les principes généraux avec des exemples de Côte d''Ivoire.\n\n## Les types de contrats de travail\n\n### 1. Contrat à Durée Indéterminée (CDI)\n**Le contrat de référence**, le plus protecteur pour le salarié.\n\n**Période d''essai (Côte d''Ivoire) :**\n- Cadres : 3 mois renouvelable une fois\n- Agents de maîtrise : 2 mois renouvelable une fois\n- Employés et ouvriers : 1 mois renouvelable une fois\n\n**Rupture du CDI :**\nExige une cause réelle et sérieuse + respect de la procédure :\n1. Entretien préalable (convocation écrite 5 jours avant)\n2. Lettre de licenciement (3 jours après l''entretien minimum)\n3. Paiement des indemnités légales\n\n### 2. Contrat à Durée Déterminée (CDD)\nRéservé aux cas limitativement prévus :\n- Remplacement d''un salarié absent\n- Accroissement temporaire d''activité\n- Travaux saisonniers\n- Tâche précise et non durable\n\n**Durée maximale :** Variable selon les pays (6 à 24 mois selon pays et secteur)\n**Renouvellement :** En général 1 à 2 fois maximum\n**À l''issue :** Indemnité de fin de CDD (6-10% de la rémunération brute)\n\n**⚠️ Attention :** Utiliser un CDD pour un emploi permanent est une requalification en CDI par les tribunaux.\n\n### 3. Contrat de prestation de services\nPour les travailleurs indépendants (freelances, consultants).\n**Pas de lien de subordination** → pas de protection du Code du Travail.\n**Risque de requalification** si le prestataire travaille exclusivement pour vous, sous vos directives.\n\n## Les clauses essentielles du contrat\n\n### Mentions obligatoires\n- Identité des parties\n- Date de début et durée (si CDD)\n- Lieu de travail\n- Poste/qualification/catégorie professionnelle\n- Rémunération (fixe + variable)\n- Durée du travail\n- Période d''essai\n- Convention collective applicable\n\n### Clauses optionnelles importantes\n\n**Clause de confidentialité :**\nObligatoire pour les postes accédant à des informations stratégiques. Précisez la durée (pendant et après le contrat).\n\n**Clause de non-concurrence :**\nEncadrée strictement : doit prévoir une contrepartie financière, être limitée dans le temps et l''espace, et se limiter aux fonctions réellement concurrentes.\n\n**Clause de mobilité :**\nAuthorise l''employeur à muter le salarié dans d''autres établissements. Doit être précisée dès l''embauche.'),

  (v_mod5, v_course_id, 'Gérer les congés, absences et licenciements selon le droit africain', 'document', 2, false,
   E'# Congés, Absences et Ruptures du Contrat de Travail\n\n## Les congés payés annuels\n\n### Principes généraux (Côte d''Ivoire - Code du Travail)\n- **Acquisition :** 2,5 jours ouvrables par mois de travail effectif\n- **Droit plein :** 30 jours ouvrables après 12 mois\n- **Majoration ancienneté :**\n  - Après 5 ans : +1 jour par année supplémentaire\n  - Après 15 ans : +2 jours\n  - Après 20 ans : +3 jours\n\n**Règle du fractionnement :**\nLes congés peuvent être fractionnés, mais une période de 12 jours ouvrables consécutifs minimum doit être respectée.\n\n### Gestion des congés dans l''entreprise\n\n**Bonnes pratiques :**\n1. **Plan de congés annuel** : demandez les souhaits de congés en janvier\n2. **Règle du roulement** : pas plus de X% de l''équipe simultanément absent\n3. **Solde de congés** : informez chaque salarié de son solde chaque trimestre\n4. **Remplacement** : anticipez et organisez la continuité du service\n\n## Les différents types d''absences\n\n| Type d''absence | Justificatif | Rémunéré ? |\n|----------------|-------------|------------|\n| Maladie | Certificat médical | Selon ancienneté/convention |\n| Accident du travail | Déclaration + certificat | Oui (CNPS) |\n| Maternité | Certificat médical | Oui (CNPS) |\n| Événements familiaux | Pièces justificatives | Oui (3-5 jours selon événement) |\n| Formation | Accord employeur | Selon accord |\n| Grève | - | Non |\n\n### Maternité en Côte d''Ivoire\n- **Durée :** 14 semaines (6 avant + 8 après l''accouchement)\n- **Indemnité :** versée par la CNPS (66% du salaire)\n- **Protection :** interdiction de licencier pendant la grossesse et le congé maternité\n\n## Les procédures disciplinaires\n\n### L''échelle des sanctions\n1. Avertissement verbal\n2. Avertissement écrit\n3. Mise à pied disciplinaire (suspension sans salaire)\n4. Licenciement pour faute\n\n### La faute simple vs faute grave vs faute lourde\n\n**Faute simple :** justifie le licenciement avec préavis et indemnités\n**Faute grave :** justifie le licenciement sans préavis, mais avec indemnités de licenciement\n**Faute lourde :** justifie le licenciement sans préavis ni indemnités\n\nExemples de fautes lourdes :\n- Vol, détournement de fonds\n- Actes de violence\n- Ivresse habituelle au travail\n- Divulgation de secrets professionnels\n\n### Procédure de licenciement\n1. **Convocation** à un entretien préalable (écrit, 5 jours minimum avant)\n2. **Entretien préalable** : vous expliquez les motifs, le salarié se défend\n3. **Délai de réflexion** (3 jours ouvrables)\n4. **Notification** du licenciement par lettre recommandée\n5. **Préavis** à exécuter ou indemniser\n6. **Paiement** des indemnités légales + solde de tout compte\n\n## Calcul des indemnités de licenciement (Côte d''Ivoire)\n\n```\nIndemnité = Salaire mensuel moyen × Coefficient\n\nCoefficients :\n- 1ère à 5ème année : 20%/an d''ancienneté\n- 6ème à 10ème année : 25%/an\n- 11ème et au-delà : 30%/an\n\nExemple : Salarié avec 8 ans d''ancienneté, salaire 300 000 XOF\n- 5 premières années : 5 × 20% × 300 000 = 300 000 XOF\n- 6ème à 8ème année : 3 × 25% × 300 000 = 225 000 XOF\n- Total : 525 000 XOF\n```'),

  (v_mod5, v_course_id, 'La CNPS et la protection sociale des salariés en Afrique', 'document', 3, false,
   E'# CNPS et Protection Sociale des Salariés\n\n## La Caisse Nationale de Prévoyance Sociale (CNPS)\n\nEn Côte d''Ivoire, la CNPS assure la protection sociale des salariés du secteur privé. Des organismes similaires existent dans chaque pays :\n- **Sénégal :** IPRES + CSS\n- **Cameroun :** CNPS\n- **Mali :** INPS\n- **Bénin :** CNSS\n\n## Les prestations de la CNPS (Côte d''Ivoire)\n\n### 1. Accidents du travail et maladies professionnelles\n- **Prise en charge médicale complète**\n- **Indemnités journalières** pendant l''incapacité\n- **Rente d''incapacité permanente** en cas de séquelles\n- **Capital décès** pour les ayants droit\n\n### 2. Allocations familiales\n- **Allocation prénatale :** versée à la 4ème, 7ème et 9ème mois de grossesse\n- **Allocation de maternité :** après accouchement\n- **Allocations familiales :** pour chaque enfant de moins de 14 ans (ou 21 ans si études)\n\n### 3. Retraite\n- **Conditions :** 60 ans d''âge + 15 ans de cotisations minimum\n- **Calcul de la pension :** basé sur le salaire moyen et la durée de cotisation\n- **Pension minimum :** fixée par arrêté ministériel\n\n## Obligations de l''employeur\n\n### Immatriculation\nTout employeur doit s''immatriculer à la CNPS **avant l''embauche du premier salarié**. Chaque salarié doit également être immatriculé.\n\n### Déclarations\n\n**Déclaration Nominative Trimestrielle :**\nDépôt trimestriel de la liste des salariés avec salaires cotisables.\n\n**Déclaration d''Accidents du Travail :**\nDans les 48h suivant tout accident du travail.\n\n### Cotisations CNPS (Côte d''Ivoire)\n\n| Branche | Taux employeur | Taux salarié |\n|---------|---------------|-------------|\n| Retraite | 7,7% | 6,3% |\n| Allocations familiales | 5,75% | 0% |\n| Accidents du travail | 2-5% (selon risques) | 0% |\n| **Total** | **~16%** | **6,3%** |\n\n```\nExemple pour un salaire brut de 500 000 XOF :\nCotisation employeur : 500 000 × 16% = 80 000 XOF\nCotisation salarié : 500 000 × 6,3% = 31 500 XOF\nTotal CNPS à verser : 111 500 XOF\n```\n\n## Construire une protection sociale complémentaire\n\nLa CNPS offre une protection minimale. Pour attirer et fidéliser les talents, proposez :\n\n- **Assurance maladie complémentaire** (AMC) : prise en charge soins non couverts par la CNPS\n- **Prévoyance décès-invalidité** : capital ou rente pour la famille\n- **Complémentaire retraite** : plan d''épargne entreprise\n- **Mutuelle santé** : tarifs négociés pour soins courants\n\n**Coût moyen AMC :** 15 000 à 50 000 XOF/mois/salarié selon niveau de couverture\n**ROI :** réduction de l''absentéisme maladie, fidélisation, attractivité'),

  -- Module 6 : Rémunération
  (v_mod6, v_course_id, 'Concevoir une politique de rémunération attractive et équitable', 'document', 1, false,
   E'# Politique de Rémunération\n\n## Les composantes de la rémunération globale\n\n### 1. Rémunération directe\n- **Salaire fixe :** base mensuelle garantie\n- **Variable individuel :** prime sur objectifs personnels\n- **Variable collectif :** participation aux bénéfices, prime d''équipe\n- **Primes exceptionnelles :** fin d''année, ancienneté, fidélité\n\n### 2. Avantages en nature\n- Véhicule de fonction ou allocation transport\n- Logement de fonction ou allocation logement\n- Téléphone / PC portable\n- Repas ou tickets restaurant\n- Carburant\n\n### 3. Protection sociale\n- Assurance maladie complémentaire\n- Retraite complémentaire\n- Prévoyance décès\n\n### 4. Avantages non monétaires\n- Formation et développement professionnel\n- Flexibilité des horaires\n- Télétravail\n- Congés supplémentaires\n- Environnement de travail\n- Titre et responsabilités\n\n## La grille salariale : construire une structure équitable\n\n### Étape 1 : Classification des postes\nRegroupez les postes par niveau de responsabilité et de complexité :\n- **Niveau 1 :** Postes d''exécution (opérateurs, caissiers, agents)\n- **Niveau 2 :** Postes qualifiés (techniciens, vendeurs confirmés)\n- **Niveau 3 :** Postes maîtrise (superviseurs, chefs d''équipe)\n- **Niveau 4 :** Cadres (responsables de département)\n- **Niveau 5 :** Cadres supérieurs (directeurs)\n\n### Étape 2 : Benchmarking salarial\nConnaissez le marché :\n- Enquêtes salariales sectorielles (CGECI, cabinets RH)\n- Offres d''emploi concurrentes\n- Réseau professionnel RH\n- Conventions collectives de votre secteur\n\n### Étape 3 : Définir des fourchettes\nPour chaque niveau : minimum / médiane / maximum\n\n```\nNiveau 3 (Maîtrise) : 250 000 - 350 000 - 450 000 XOF\n                       (débutant)  (confirmé) (senior)\n```\n\n## Les primes de performance\n\n### Conception d''un système de primes efficace\n\n**Principes :**\n1. **Simple à comprendre** : le collaborateur doit pouvoir calculer sa prime lui-même\n2. **Atteignable** : 80% des collaborateurs doivent pouvoir atteindre le minimum\n3. **Significatif** : la prime doit représenter au moins 10% du fixe pour motiver\n4. **Rapide** : versement proche de l''acte qui a généré la performance\n\n**Structure recommandée pour force de vente :**\n```\nObjectif 100% : prime 50 000 XOF\n\nRéalisation 80-89% : prime 25 000 XOF\nRéalisation 90-99% : prime 40 000 XOF\nRéalisation 100-109% : prime 50 000 XOF\nRéalisation 110-119% : prime 65 000 XOF\nRéalisation ≥ 120% : prime 80 000 XOF\n```'),

  (v_mod6, v_course_id, 'Fidéliser les talents : au-delà du salaire', 'document', 2, false,
   E'# Fidéliser les Talents en Afrique\n\n## Le coût du turnover : pourquoi fidéliser coûte moins que remplacer\n\nRemplacer un collaborateur coûte en moyenne **3 à 6 mois de salaire** :\n- Coût du recrutement (annonces, tests, entretiens)\n- Coût de la vacance du poste\n- Coût de la formation du remplaçant\n- Coût de la perte de productivité pendant la montée en compétences\n- Coût du transfert de connaissance perdu\n\nInvestir dans la fidélisation est toujours plus rentable.\n\n## Ce qui fait vraiment rester les talents africains\n\nL''argent est important mais insuffisant. Une étude PwC Afrique montre que les top talents quittent pour :\n1. **Manque de perspectives d''évolution** (54%)\n2. **Mauvaise relation avec le manager** (38%)\n3. **Ambiance et culture** (35%)\n4. **Salaire insuffisant** (31%)\n5. **Manque de reconnaissance** (28%)\n\n## Les 5 leviers de fidélisation\n\n### 1. Les perspectives de carrière\n- Plan de carrière individuel à 3-5 ans\n- Mobilité interne prioritaire aux recrutements externes\n- Rotation des postes pour développer les compétences\n- Participation aux projets stratégiques\n\n**Entretien annuel de développement :**\n- "Où vous voyez-vous dans 3 ans ?"\n- "Quelles compétences voulez-vous développer ?"\n- "Comment l''entreprise peut-elle vous aider à y arriver ?"\n\n### 2. La qualité du management\nLes collaborateurs quittent leur manager, pas leur entreprise.\n- Formation des managers au feedback et au coaching\n- Évaluation des managers par leurs équipes (360°)\n- Mobilité ou support des managers toxiques\n\n### 3. La culture et le sens\n- Mission d''entreprise qui dépasse le profit\n- Implication dans les décisions (consultation, comité d''entreprise)\n- Fierté d''appartenance (communication sur les succès)\n- Équilibre vie pro/perso (horaires flexibles, télétravail possible)\n\n### 4. La reconnaissance non financière\n\n**Reconnaissance immédiate :**\n- Remerciement personnel et spécifique dans les 24h\n- Félicitations en public en réunion\n- Message personnel du dirigeant\n\n**Reconnaissance à moyen terme :**\n- Mention dans la newsletter interne\n- Remise d''un trophée ou diplôme lors d''une cérémonie\n- Sponsoring d''une formation de leur choix\n\n**Reconnaissance à long terme :**\n- Prime d''ancienneté significative à 5, 10, 15 ans\n- Voyage ou week-end offert au couple\n- Action dans l''entreprise (si SARL)\n\n### 5. Les conditions de travail\n\n**En Afrique, les basiques font la différence :**\n- Climatisation ou ventilation correcte\n- Eau potable disponible\n- Transports facilités (bus d''entreprise, allocation)\n- Repas du midi (restaurant d''entreprise ou allocation)\n- Toilettes propres et fonctionnelles\n- Espaces de repos\n\n## L''entretien de départ : apprendre pour améliorer\n\nQuand un collaborateur part, réalisez toujours un entretien de départ :\n- Qu''est-ce qui vous a amené à chercher ailleurs ?\n- Qu''aurait pu faire l''entreprise pour vous garder ?\n- Qu''est-ce que vous appréciez le plus dans votre passage ?\n- Que conseilleriez-vous à votre successeur ?\n\nCes données valent de l''or pour votre politique RH.'),

  -- Module 7 : SIRH
  (v_mod7, v_course_id, 'SIRH : choisir et mettre en place un logiciel RH pour PME', 'document', 1, false,
   E'# SIRH pour PME Africaines\n\n## Qu''est-ce qu''un SIRH ?\nUn Système d''Information RH (SIRH) est un logiciel qui centralise et automatise la gestion des ressources humaines : paie, congés, recrutement, formation, évaluation.\n\n## Pourquoi digitaliser les RH ?\n\n**Avant le SIRH :**\n- Fiches de paie Excel, erreurs fréquentes\n- Suivi des congés sur papier, désaccords\n- Dossiers salariés en classeurs, difficilement accessibles\n- Déclarations CNPS manuelles, risques d''oubli\n\n**Après le SIRH :**\n- Paie calculée automatiquement, zéro erreur\n- Demandes de congés en ligne, validation par email\n- Dossiers salariés numériques, accessibles en 2 clics\n- Déclarations CNPS générées automatiquement\n\n## Les logiciels RH adaptés aux PME africaines\n\n### Solutions locales / régionales\n\n**Sage Paie (Afrique)**\n- Paramétré pour les codes du travail africains (CI, Sénégal, Cameroun...)\n- Calcul automatique de la paie OHADA\n- Interface en français\n- **Coût :** 200 000 - 500 000 XOF/an selon version\n\n**Eurécia**\n- SIRH complet en cloud\n- Adapté pour l''Afrique francophone\n- **Coût :** ~5 000 XOF/salarié/mois\n\n**Odoo RH (open source)**\n- Module RH complet\n- Personnalisable pour les spécificités locales\n- **Coût :** gratuit (open source) + coût d''implémentation\n\n### Solutions internationales adaptables\n**BambooHR, HiBob :**\n- Très complets, interface intuitive\n- Nécessitent paramétrage pour le droit africain\n- **Coût :** 15-30 USD/salarié/mois\n\n## Déployer un SIRH en 4 phases\n\n### Phase 1 : Audit et paramétrage (Mois 1-2)\n- Cartographie de vos processus RH actuels\n- Collecte des données salariés (dossiers papier → numérique)\n- Paramétrage des rubriques de paie selon votre convention collective\n- Configuration des workflows d''approbation\n\n### Phase 2 : Formation et pilote (Mois 3)\n- Formation des RH et des managers\n- Déploiement sur un département pilote\n- Corrections des anomalies\n\n### Phase 3 : Déploiement général (Mois 4-5)\n- Formation de tous les salariés (accès au self-service)\n- Migration des données historiques\n- Double vérification avec l''ancienne méthode pendant 1 mois\n\n### Phase 4 : Optimisation (Mois 6+)\n- Analyse des tableaux de bord RH\n- Automatisation des déclarations sociales\n- Intégration avec la comptabilité\n\n## Le self-service salarié : responsabiliser les équipes\n\nDonnez à vos salariés accès à :\n- Leurs bulletins de salaire en ligne (téléchargeables)\n- Leur solde de congés en temps réel\n- La demande de congés en ligne\n- Leurs documents RH (contrat, avenants)\n- La mise à jour de leurs informations personnelles\n\n**Résultat :** -60% de sollicitations administratives auprès des RH');

END $$;


-- ============================================================
-- FORMATION 8 : E-commerce et Vente en Ligne en Afrique
-- ============================================================
DO $$ DECLARE
  v_course_id uuid;
  v_mod5 uuid; v_mod6 uuid; v_mod7 uuid;
  v_max_pos int;
BEGIN
  SELECT id INTO v_course_id FROM courses WHERE slug = 'ecommerce-vente-en-ligne-afrique';
  SELECT COALESCE(MAX(position), 0) INTO v_max_pos FROM modules WHERE course_id = v_course_id;

  INSERT INTO modules (course_id, title, position) VALUES
    (v_course_id, 'Logistique et Livraison : Le Défi n°1 du E-commerce Africain', v_max_pos + 1),
    (v_course_id, 'Service Client Digital et Gestion des Avis', v_max_pos + 2),
    (v_course_id, 'Analytics E-commerce et Croissance du Chiffre d''Affaires', v_max_pos + 3);

  SELECT id INTO v_mod5 FROM modules WHERE course_id = v_course_id ORDER BY position OFFSET v_max_pos LIMIT 1;
  SELECT id INTO v_mod6 FROM modules WHERE course_id = v_course_id ORDER BY position OFFSET v_max_pos + 1 LIMIT 1;
  SELECT id INTO v_mod7 FROM modules WHERE course_id = v_course_id ORDER BY position OFFSET v_max_pos + 2 LIMIT 1;

  INSERT INTO lessons (module_id, course_id, title, type, position, is_free_preview, content) VALUES

  (v_mod5, v_course_id, 'Maîtriser la logistique de livraison en Afrique', 'document', 1, false,
   E'# Logistique E-commerce en Afrique\n\n## Le paradoxe logistique africain\nL''Afrique a le plus fort potentiel de croissance e-commerce mondial, mais aussi les défis logistiques les plus complexes :\n- Adresses postales inexistantes ou imprécises\n- Infrastructure routière variable\n- Coût de livraison élevé relatif au panier moyen\n- Taux de retour élevé (paiement à la livraison dominant)\n- Zones rurales difficiles à atteindre\n\n## Les modèles de livraison disponibles\n\n### 1. Livraison en propre (votre propre flotte)\n**Pour :** Boutiques avec volume suffisant dans une ville\n**Avantages :** Contrôle total, image de marque, pas de commissions\n**Inconvénients :** Coût fixe élevé, gestion complexe\n**Recommandé si :** > 30 commandes/jour dans votre ville\n\n### 2. Partenaires logistiques spécialisés e-commerce\n\n**Côte d''Ivoire :**\n- **Jumia Logistics :** livraison dans tout le pays, tarifs compétitifs\n- **Glovo / Yango Delivery :** livraison express même le jour J\n- **DHL Afrique :** pour le cross-border (exportation)\n- **Colissimo local :** Poste de Côte d''Ivoire (limites de couverture)\n\n**Sénégal :**\n- **Yobantel :** livraison nationale\n- **DakarPost :** réseau capillaire\n\n**Paramètres à négocier :**\n- Prix par colis selon poids et zone\n- Délai de livraison garanti\n- Procédure en cas de colis endommagé ou perdu\n- Fréquence et mode des remises de caisse\n\n### 3. Points relais (click & collect)\nRéseau de boutiques physiques partenaires où les clients viennent récupérer leurs commandes.\n\n**Avantages :**\n- Coût de livraison réduit de 30-50%\n- Taux d''échec livraison quasi nul\n- Opportunité de ventes additionnelles au point relais\n\n**Comment créer votre réseau :**\n- Identifier des boutiques dans chaque quartier clé\n- Convention de partenariat (commission 500-1000 XOF/colis)\n- Application ou interface pour le suivi des colis\n\n## Gérer le paiement à la livraison (PAL)\n\nEn Afrique, **60-80% des achats e-commerce sont payés à la livraison**. C''est une réalité incontournable.\n\n**Risques du PAL :**\n- Taux de refus à la livraison : 15-25% en moyenne\n- Immobilisation du stock livré non payé\n- Coût du retour (doublement des frais de livraison)\n\n**Comment réduire le taux de refus :**\n1. **Confirmation téléphonique** avant chaque livraison ("Votre commande est en route, confirmez votre disponibilité")\n2. **Délai de livraison court** : < 48h (moins de temps pour changer d''avis)\n3. **Processus simple** : le livreur apporte monnaie, pas de problème pour les billets\n4. **Politique de retour claire** : "Satisfait ou remboursé" réduit l''anxiété et paradoxalement les retours\n\n## Les métriques logistiques à suivre\n\n| Métrique | Formule | Objectif |\n|----------|---------|----------|\n| Taux de livraison réussie | Livraisons OK / Total commandes | > 85% |\n| Délai moyen de livraison | Σ délais / Nb livraisons | < 3 jours |\n| Taux de refus PAL | Refus / Commandes PAL | < 15% |\n| Coût logistique / CA | Frais livraison / CA | < 8% |\n| Satisfaction livraison | Note client post-livraison | > 4/5 |'),

  (v_mod5, v_course_id, 'Vendre sur les marketplaces africaines : Jumia, Glovo et autres', 'document', 2, false,
   E'# Vendre sur les Marketplaces Africaines\n\n## L''écosystème des marketplaces en Afrique\n\n### Jumia — Le leader continental\n**Présence :** CI, Sénégal, Nigeria, Kenya, Ghana, Maroc et +\n**Catégories fortes :** Électronique, Mode, Beauté, Maison\n**Trafic :** Des millions de visiteurs/mois\n\n**Comment vendre sur Jumia :**\n1. Inscription Jumia Seller : seller.jumia.com/[pays]\n2. Vérification des documents (registre commerce, NIF)\n3. Création des fiches produits\n4. Envoi des stocks au hub Jumia OU livraison en propre\n5. Jumia gère le paiement et vous reverse (toutes les 2 semaines)\n\n**Commissions Jumia :** 5% à 25% selon catégorie\n\n### Glovo / Yango — Livraison rapide\n**Modèle :** Livraison express de produits (food, épicerie, pharmacie, fleurs...)\n**Avantage :** Livraison < 30-60 minutes\n**Pour qui :** Restaurants, épiceries, pharmacies, fleuristes\n\n### Facebook Marketplace\n**Gratuit**, très utilisé en Afrique de l''Ouest pour :\n- Vêtements d''occasion\n- Électronique d''occasion\n- Meubles et électroménager\n- Articles locaux\n\n**Limite :** Pas de système de paiement intégré, paiement à la livraison.\n\n### Instagram Shopping\n**Idéal pour :** Mode, beauté, artisanat, décoration\n**Fonctionnalités :** Tags produits dans les posts, boutique Instagram\n\n### WhatsApp Business Catalog\n**Catalogue de produits dans WhatsApp Business**\n- Partagez le lien de votre catalogue dans vos discussions\n- Commande par WhatsApp, paiement mobile money\n- Parfait pour les petites structures sans site web\n\n## Stratégie multicanale recommandée\n\n**Phase 1 (Démarrage) :** WhatsApp + Instagram\n- Coût zéro\n- Validation rapide du produit\n- Construction d''une communauté\n\n**Phase 2 (Croissance) :** + Marketplace (Jumia) + Site propre\n- Volume et notoriété via marketplace\n- Marge et fidélisation via site propre\n\n**Phase 3 (Maturité) :** Omnicanal intégré\n- Boutique physique + e-commerce\n- Gestion centralisée des stocks\n- CRM unifié\n\n## Optimiser vos fiches produits pour vendre plus\n\n### La fiche produit parfaite\n\n**Titre :** Produit + caractéristiques clés + marque\n❌ "Chaussure femme"\n✅ "Chaussure Talon Bloc Femme — Cuir Synthétique — Talon 7cm — Noir/Bordeaux — Taille 36-41"\n\n**Photos :**\n- Minimum 5 photos\n- Fond blanc pour la principale\n- Produit porté/utilisé\n- Détails gros plan\n- Guide des tailles si applicable\n\n**Description :**\n- Bénéfices avant caractéristiques\n- Répondre aux questions fréquentes\n- Préciser les dimensions/tailles\n- Politique de retour\n\n**Prix :**\n- Comparez avec les concurrents sur la plateforme\n- Prix légèrement sous la médiane pour démarrer\n- Participez aux promotions de la marketplace (Black Friday, soldes...)'),

  -- Module 6 : Service client
  (v_mod6, v_course_id, 'Construire un service client e-commerce d''excellence', 'document', 1, false,
   E'# Service Client E-commerce d''Excellence\n\n## Pourquoi le service client est votre avantage concurrentiel\n\nEn e-commerce africain, la confiance est tout. Le client ne peut pas toucher le produit, ne vous connaît peut-être pas. Un service client exceptionnel est ce qui le fera acheter chez vous plutôt que chez un concurrent.\n\n**Statistiques clés :**\n- 89% des clients cessent d''acheter après une mauvaise expérience service\n- Un client satisfait recommande à 3-5 personnes\n- Un client insatisfait le dit à 9-15 personnes (et sur les réseaux)\n- Il coûte 5x plus cher d''acquérir un nouveau client que de fidéliser un existant\n\n## Les canaux de service client et leur gestion\n\n### WhatsApp Business — Canal prioritaire en Afrique\n\n**Configuration indispensable :**\n- Message de bienvenue automatique\n- Message d''absence (horaires hors service)\n- Étiquettes : Nouveau client, En attente, Résolu, VIP\n- Réponses rapides (templates pour questions fréquentes)\n\n**Temps de réponse visé :** < 15 minutes pendant les heures d''ouverture\n\n**Templates de réponses rapides :**\n```\n/livraison → "Votre commande sera livrée dans [X] heures/jours. Notre livreur vous appellera avant passage."\n\n/stock → "Ce produit est actuellement [disponible/en rupture]. [Alternative si rupture]."\n\n/retour → "Nous acceptons les retours sous 7 jours. Produit non utilisé, dans son emballage d''origine. Envoyez-nous une photo du produit + votre numéro de commande."\n```\n\n### Facebook Messenger et Instagram DM\n- Activez les réponses automatiques\n- Objectif : réponse sous 1h\n- Les commentaires publics non répondus nuisent à votre image\n\n### Email\n- Template de confirmation de commande automatique\n- Template de suivi de livraison\n- Template de demande d''avis post-livraison\n\n## Gérer les situations difficiles\n\n### Le client insatisfait (produit non conforme)\n```\nÉtape 1 : Reconnaître le problème SANS se justifier\n"Je comprends votre déception et je m''en excuse sincèrement."\n\nÉtape 2 : Proposer une solution IMMÉDIATE\n"Voici ce que je vous propose : [remboursement / échange / bon de réduction]"\n\nÉtape 3 : Agir VITE\nRéglez le problème dans les 24h maximum.\n\nÉtape 4 : Suivre\nRecontactez le client 48h après pour s''assurer de sa satisfaction.\n```\n\n### Le client agressif sur les réseaux\n- Ne jamais répondre à chaud\n- Sortir de la confrontation publique : "Pouvez-vous nous contacter en DM ?"\n- En privé, appliquer le même processus que ci-dessus\n- Ne jamais supprimer un commentaire négatif (sauf injure/menace)\n\n### La fraude et les faux refus de livraison\n- Photo/vidéo du colis avant livraison (preuve d''intégrité)\n- Signature de remise + photo du destinataire (avec accord)\n- Blocage des numéros/adresses de fraudeurs récidivistes\n\n## Mesurer la satisfaction client\n\n### NPS (Net Promoter Score)\n**Question :** "Sur une échelle de 0 à 10, recommanderiez-vous notre boutique à un ami ?"\n\n- **Promoteurs (9-10) :** clients enthousiastes → demandez-leur un avis Google\n- **Passifs (7-8) :** satisfaits mais pas convaincus → identifiez comment les améliorer\n- **Détracteurs (0-6) :** insatisfaits → contactez-les pour comprendre et résoudre\n\n```\nNPS = % Promoteurs - % Détracteurs\nNPS > 50 : Excellent\nNPS 30-50 : Bien\nNPS 0-30 : À améliorer\nNPS < 0 : Urgence\n```'),

  -- Module 7 : Analytics
  (v_mod7, v_course_id, 'Analytics e-commerce : optimiser votre taux de conversion', 'document', 1, false,
   E'# Analytics E-commerce et Optimisation des Conversions\n\n## Les métriques fondamentales du e-commerce\n\n### 1. Taux de conversion (CR)\n```\nCR = (Nombre de commandes / Visiteurs) × 100\nBenchmark Afrique : 1-3%\nObjectif : > 2%\n```\n\nSi 1000 personnes visitent votre site et 15 commandent → CR = 1,5%\n\n### 2. Valeur Moyenne de Commande (AOV — Average Order Value)\n```\nAOV = CA total / Nombre de commandes\n```\nStratégies pour augmenter l''AOV :\n- Upsell (version premium du produit)\n- Cross-sell (produits complémentaires)\n- Bundle (packs à prix réduit)\n- Livraison gratuite à partir d''un seuil\n\n### 3. Customer Lifetime Value (CLV)\n```\nCLV = AOV × Fréquence d''achat × Durée de rétention\n```\nUn client qui achète 25 000 XOF, 4 fois par an, pendant 3 ans :\nCLV = 25 000 × 4 × 3 = 300 000 XOF\n\n### 4. Coût d''Acquisition Client (CAC)\n```\nCAC = Dépenses marketing / Nouveaux clients acquis\n```\nRègle : CAC < CLV/3\n\n### 5. Taux d''abandon de panier\n```\nTaux abandon = (1 - Commandes / Ajouts panier) × 100\nBenchmark : 65-75%\n```\n\n## Optimiser le tunnel de conversion\n\n### Les 5 étapes du tunnel e-commerce\n```\nVisiteur → Visiteur page produit → Ajout panier → Checkout → Commande\n  1000         600 (60%)            300 (50%)      150 (50%)   15 (10%)\n```\n\n**Analyser chaque étape pour identifier où vous perdez des clients.**\n\n### Optimisation de la page produit\n- Photo haute qualité (chargement rapide sur mobile)\n- Prix clairement visible\n- Bouton "Ajouter au panier" visible sans scroller\n- Avis clients (minimum 5 avis pour crédibilité)\n- FAQ sur les questions courantes\n- Garantie et politique de retour visible\n\n### Optimisation du checkout\n- Minimum d''étapes (idéalement 1 page)\n- Paiement Mobile Money en premier (Wave, Orange Money)\n- Option "Commander sans créer de compte"\n- Récapitulatif clair de la commande\n- Confiance : logo sécurité, avis, numéro de téléphone\n\n### Récupération des paniers abandonnés\nAutomatisation en 3 temps :\n- **H+1 :** WhatsApp/SMS "Vous avez oublié quelque chose dans votre panier"\n- **H+24 :** Email avec photo du produit + bouton de retour\n- **H+48 :** Offre spéciale (-5% ou livraison gratuite) pour finaliser\n\n## Outils analytics recommandés\n\n**Google Analytics 4 :** Comportement visiteurs, sources de trafic\n**Meta Pixel :** Tracking conversions depuis Facebook/Instagram\n**Hotjar :** Heatmaps (où cliquent vos visiteurs), enregistrements de sessions\n**Google Search Console :** Mots-clés qui amènent du trafic organique\n\n## Tests A/B : améliorer par l''expérimentation\n\nPrincipe : Testez 2 versions d''un élément, gardez la meilleure.\n\nExemples :\n- Bouton vert vs bouton orange → quel taux de clic ?\n- "Acheter maintenant" vs "Ajouter au panier" → quelle conversion ?\n- Prix rond (15 000 XOF) vs prix psychologique (14 900 XOF) → quel impact ?\n- Photo produit seul vs photo produit porté → quelles ventes ?\n\n**Durée minimale d''un test :** 2 semaines, 500 visiteurs par version minimum');

END $$;


-- ============================================================
-- FORMATION 9 : Intelligence Artificielle & Outils IA pour Professionnels Africains
-- ============================================================
DO $$ DECLARE
  v_course_id uuid;
  v_mod5 uuid; v_mod6 uuid; v_mod7 uuid;
  v_max_pos int;
BEGIN
  SELECT id INTO v_course_id FROM courses WHERE slug = 'intelligence-artificielle-outils-ia-professionnels';
  SELECT COALESCE(MAX(position), 0) INTO v_max_pos FROM modules WHERE course_id = v_course_id;

  INSERT INTO modules (course_id, title, position) VALUES
    (v_course_id, 'IA et Productivité Avancée : Automatiser son Travail avec l''IA', v_max_pos + 1),
    (v_course_id, 'IA pour Entrepreneurs Africains : Applications Concrètes', v_max_pos + 2),
    (v_course_id, 'Éthique de l''IA, Biais et Futur du Travail en Afrique', v_max_pos + 3);

  SELECT id INTO v_mod5 FROM modules WHERE course_id = v_course_id ORDER BY position OFFSET v_max_pos LIMIT 1;
  SELECT id INTO v_mod6 FROM modules WHERE course_id = v_course_id ORDER BY position OFFSET v_max_pos + 1 LIMIT 1;
  SELECT id INTO v_mod7 FROM modules WHERE course_id = v_course_id ORDER BY position OFFSET v_max_pos + 2 LIMIT 1;

  INSERT INTO lessons (module_id, course_id, title, type, position, is_free_preview, content) VALUES

  (v_mod5, v_course_id, 'Maîtriser le prompt engineering pour des résultats professionnels', 'document', 1, false,
   E'# Prompt Engineering Avancé\n\n## Pourquoi les prompts font toute la différence\n\nChatGPT, Claude, Gemini sont des outils extraordinaires — mais leur qualité dépend à 80% de la qualité de vos instructions. Un prompt médiocre donne un résultat médiocre. Un prompt expert donne un résultat expert.\n\n**Règle fondamentale :** L''IA est comme un consultant brillant mais qui n''a aucun contexte sur votre situation. Plus vous lui en donnez, meilleur sera le résultat.\n\n## La structure TRACI du prompt parfait\n\n### T — Tâche (Task)\nQue voulez-vous exactement ?\n```\n❌ "Aide-moi avec mon marketing"\n✅ "Rédige 3 accroches publicitaires pour Facebook Ads"\n```\n\n### R — Rôle (Role)\nQuel expert doit se comporter l''IA ?\n```\n"Tu es un expert en marketing digital spécialisé dans les PME africaines avec 15 ans d''expérience..."\n```\n\n### A — Audience\nPour qui est le contenu ?\n```\n"...pour des commerçants ivoiriens de 35-50 ans, peu familiers du digital..."\n```\n\n### C — Contexte\nQuelle est votre situation ?\n```\n"...Je vends des condiments artisanaux bio fabriqués à Abidjan. Prix : 3500 XOF la bouteille. Mes clients actuels sont les expatriés et les cadres supérieurs..."\n```\n\n### I — Instructions de format\nComment doit être présenté le résultat ?\n```\n"...Présente les accroches en bullet points. Maximum 125 caractères par accroche. Inclus un emoji par accroche. Ton : chaleureux et authentique, pas corporate."\n```\n\n## Prompt complet assemblé\n\n```\nTu es un expert en marketing digital spécialisé dans les PME africaines.\n\nContexte : Je vends des condiments artisanaux bio fabriqués à Abidjan (sauce piment, gingembre, djèkè). Prix : 3500 XOF. Cible : expatriés et cadres supérieurs qui recherchent des produits sains et locaux.\n\nTâche : Rédige 5 accroches pour des publicités Facebook.\n\nFormat :\n- Une accroche par ligne\n- Maximum 125 caractères\n- 1 emoji par accroche\n- Ton chaleureux et authentique\n- Mets en avant la qualité artisanale et l''origine ivoirienne\n```\n\n## Techniques avancées de prompting\n\n### Le chain of thought (raisonnement par étapes)\n```\nAvant de me donner ta réponse, réfléchis étape par étape :\n1. Analyse la situation\n2. Identifie les contraintes\n3. Génère plusieurs options\n4. Choisis la meilleure avec justification\n```\n\n### Le few-shot prompting (exemples)\n```\nVoici des exemples du style que je veux :\nExemple 1 : [votre texte idéal 1]\nExemple 2 : [votre texte idéal 2]\n\nMaintenant génère un texte similaire sur [sujet].\n```\n\n### L''itération\nL''IA s''améliore au fil de la conversation :\n1. Premier prompt → résultat de base\n2. "C''est bien, mais rends-le plus [adjectif]"\n3. "Refais la 3ème option en version plus courte"\n4. "Combine les meilleures parties du 1 et du 3"\n\n## Promptes essentiels pour professionnels africains\n\n**Email professionnel :**\n```\nRédige un email professionnel en français pour [situation]. Destinataire : [rôle]. Objectif : [ce que je veux obtenir]. Ton : [formel/chaleureux/etc]. Longueur : [court/modéré/long].\n```\n\n**Analyse de données :**\n```\nVoici mes données : [tableau]. Analyse-les et dis-moi : 1) Les 3 insights les plus importants. 2) Les anomalies ou points d''attention. 3) 2 recommandations concrètes basées sur ces données.\n```\n\n**Préparation réunion :**\n```\nJe dois présenter [sujet] à [audience] en [durée]. Aide-moi à créer un plan structuré avec les points clés, les questions potentielles et mes meilleures réponses.\n```'),

  (v_mod5, v_course_id, 'Automatiser ses tâches avec Make, Zapier et les API IA', 'document', 2, false,
   E'# Automatisation avec Make et Zapier\n\n## Qu''est-ce que l''automatisation sans code ?\nMake (anciennement Integromat) et Zapier sont des plateformes qui connectent vos applications entre elles et automatisent les flux de travail — sans écrire une seule ligne de code.\n\n**Principe :** Si [événement A] se produit dans l''application X, alors [action B] dans l''application Y.\n\n**Exemples :**\n- "Si quelqu''un remplit mon formulaire Google → envoie-lui un email WhatsApp de bienvenue + ajoute-le dans mon CRM"\n- "Si je reçois une commande sur ma boutique → crée une tâche dans Notion + informe le livreur par SMS"\n- "Chaque lundi → génère un rapport depuis Google Analytics + envoie-le par email à la direction"\n\n## Make vs Zapier : laquelle choisir ?\n\n| Critère | Make | Zapier |\n|---------|------|--------|\n| Prix | 9$/mois (500 ops) | 20$/mois (750 tâches) |\n| Complexité | Plus technique | Plus simple |\n| Flexibilité | Très haute | Moyenne |\n| Apps disponibles | 1000+ | 5000+ |\n| **Recommandé pour** | PME avec besoins complexes | Débutants et cas simples |\n\n## Automatisations essentielles pour PME africaines\n\n### 1. Automatisation des leads\n```\nDéclencheur : Formulaire Google soumis\n→ Action 1 : Ajouter le contact dans HubSpot CRM\n→ Action 2 : Envoyer un WhatsApp de bienvenue (via Brevo/Twilio)\n→ Action 3 : Créer une tâche "Rappel commercial" dans 24h\n→ Action 4 : Notifier le commercial concerné par email\n```\n\n### 2. Automatisation des commandes e-commerce\n```\nDéclencheur : Nouvelle commande WooCommerce\n→ Action 1 : Envoyer confirmation email + WhatsApp client\n→ Action 2 : Réduire le stock dans Google Sheets\n→ Action 3 : Créer bon de préparation dans Notion\n→ Action 4 : Si stock < 5 → alerter le responsable approvisionnement\n```\n\n### 3. Automatisation du contenu social\n```\nDéclencheur : Nouvel article de blog publié\n→ Action 1 : Poster automatiquement sur Facebook\n→ Action 2 : Poster sur LinkedIn avec adaptation du texte\n→ Action 3 : Envoyer newsletter email aux abonnés\n→ Action 4 : Créer rappel pour faire une story Instagram\n```\n\n## Intégrer l''IA dans vos automatisations\n\n### OpenAI dans Make/Zapier\nVous pouvez appeler GPT-4 dans vos automatisations :\n\n```\nDéclencheur : Email client reçu dans Gmail\n→ Action 1 : Analyser l''email avec GPT-4\n  Prompt : "Résume cet email et dis-moi s''il s''agit d''une demande de support, une commande, une plainte ou autre."\n→ Action 2 : Si "plainte" → alerter le responsable SAV\n  Si "commande" → créer la commande dans le CRM\n  Si "support" → assigner à l''équipe support\n```\n\n## Créer votre premier scénario Make (étape par étape)\n\n1. Créer un compte sur **make.com** (gratuit pour débuter)\n2. Cliquer "Create a new scenario"\n3. Choisir l''application déclencheur (ex : Google Forms)\n4. Configurer le déclencheur (quelle action déclenche le scénario)\n5. Ajouter un module action (ex : Gmail)\n6. Configurer l''action (rédiger l''email avec les données du formulaire)\n7. Tester avec un vrai exemple\n8. Activer le scénario\n\n**Temps de configuration :** 30-60 minutes pour un scénario simple'),

  (v_mod5, v_course_id, 'Créer du contenu professionnel avec les outils IA', 'document', 3, false,
   E'# Créer du Contenu Professionnel avec l''IA\n\n## Les outils IA de création de contenu\n\n### Texte et Rédaction\n\n**ChatGPT (OpenAI)** — Le plus populaire\n- Articles de blog, emails, rapports, propositions commerciales\n- Code informatique, formules Excel\n- Traduction et adaptation culturelle\n- Analyse de documents PDF\n\n**Claude (Anthropic)** — Raisonnement avancé\n- Analyse approfondie, synthèse de longs documents\n- Rédaction nuancée et éthique\n- Code complexe\n- Idéal pour les usages professionnels sensibles\n\n**Gemini (Google)** — Intégration Google\n- Intégré à Gmail, Google Docs, Sheets\n- Recherche web en temps réel\n- Analyse d''images\n\n### Image et Design\n\n**Canva IA (Magic Design)**\n- Génération de visuels marketing\n- Retouche photo automatique\n- Suppression d''arrière-plan\n- Texte sur image stylisé\n- **Disponible en Afrique :** Oui, version gratuite\n\n**Adobe Firefly**\n- Génération d''images professionnelles\n- Styles personnalisables\n- Intégré aux produits Adobe\n\n**DALL-E / Midjourney**\n- Génération d''images ultra-réalistes ou artistiques\n- Utile pour : illustrations blog, visuels pub, maquettes produits\n\n### Vidéo\n\n**Synthesia**\n- Vidéos avec avatar IA qui parle\n- Idéal : formations en ligne, présentations produits\n- Pas besoin de caméra ni studio\n- **Langue :** Français disponible\n\n**Descript**\n- Montage vidéo par édition du transcript\n- Sous-titres automatiques\n- Suppression des silences\n\n**CapCut IA**\n- Sous-titres automatiques\n- Effets automatiques\n- Très populaire en Afrique (gratuit, mobile)\n\n## Workflow de production de contenu IA\n\n### Créer 1 mois de contenu en 1 journée\n\n**Étape 1 (1h) : Brainstorming avec IA**\n```\nPrompt : "Je suis [expert en X]. Génère 20 idées de contenu pour LinkedIn pour [mon audience cible]. Mix : 40% conseils pratiques, 30% stories/expériences, 20% actualité sectorielle, 10% engagement/questions."\n```\n\n**Étape 2 (2h) : Rédaction des 8-10 meilleurs posts**\nPour chaque post : prompt détaillé → révision humaine → ajustement ton/style\n\n**Étape 3 (1h) : Création des visuels**\nCanva IA pour transformer chaque post en visuel attractif\n\n**Étape 4 (30min) : Programmation**\nBuffer / Later / Metricool pour programmer les publications\n\n## Garder votre voix humaine avec l''IA\n\nL''IA génère du contenu générique. Ce qui vous rend unique :\n- **Vos expériences personnelles** (ajoutez des anecdotes vraies)\n- **Votre contexte local** (exemples africains, références culturelles)\n- **Votre opinion** (l''IA hésite à prendre position, pas vous)\n- **Votre réseau** (mentionnez des personnes réelles)\n\n**Règle d''or :** Utilisez l''IA comme premier jet, pas comme version finale. Toujours réviser et personnaliser.'),

  -- Module 6 : IA pour entrepreneurs
  (v_mod6, v_course_id, 'IA pour la gestion commerciale et la relation client', 'document', 1, false,
   E'# IA pour la Gestion Commerciale\n\n## Chatbots IA : votre commercial/support 24h/24\n\n### Qu''est-ce qu''un chatbot IA ?\nUn chatbot IA répond automatiquement aux questions de vos clients sur votre site web, WhatsApp ou Facebook Messenger — 24h/24, sans salarié.\n\n**Différence chatbot classique vs chatbot IA :**\n- **Classique :** réponses prédéfinies, questions limitées\n- **IA :** comprend les questions naturelles, contextualise les réponses, apprend\n\n### Créer un chatbot IA pour votre entreprise\n\n**Option 1 : Tidio (pour site web)**\n- Intégration simple sur WordPress/Shopify\n- GPT-4 intégré\n- Répond aux questions sur vos produits, prix, horaires\n- **Coût :** ~29$/mois\n\n**Option 2 : ManyChat (pour WhatsApp/Instagram/Messenger)**\n- Automatise les conversations WhatsApp Business\n- Envoi de catalogues, prise de commandes, paiement\n- **Coût :** 15$/mois\n\n**Option 3 : Voiceflow (solution avancée)**\n- Builder visuel de chatbot sans code\n- Connexion à ChatGPT/Claude\n- Intégration CRM\n- **Coût :** 50$/mois\n\n### Ce que votre chatbot doit pouvoir faire\n1. Accueillir et qualifier les prospects\n2. Répondre aux FAQ (prix, horaires, délais, disponibilité)\n3. Prendre des rendez-vous (intégration Calendly)\n4. Escalader vers un humain si besoin\n5. Collecter des informations de contact\n\n## IA pour l''analyse des ventes et prévisions\n\n### Outils d''analytics IA\n\n**Google Looker Studio + IA (gratuit)**\nConnectez vos données de vente et obtenez des visualisations automatiques + insights IA.\n\n**Power BI (Microsoft)**\n- Prévisions de ventes automatiques\n- Détection d''anomalies\n- Recommandations business\n- **Disponible avec Microsoft 365**\n\n**Zoho Analytics**\n- IA intégrée pour les analyses prédictives\n- Adapté aux PME africaines (prix abordables)\n- **Coût :** 25$/mois\n\n### Prompts IA pour l''analyse commerciale\n\n**Analyser vos ventes :**\n```\nVoici mes données de ventes des 6 derniers mois : [collez votre tableau].\nAnalyse :\n1. Les 3 tendances principales\n2. Les produits/services sous-performants\n3. Les patterns saisonniers\n4. 3 recommandations concrètes pour améliorer les ventes du prochain trimestre\n```\n\n**Préparer votre pitch commercial :**\n```\nJe dois pitcher mon service [X] à [type de client] qui a comme problèmes principaux [Y et Z]. Prix : [montant]. Durée du pitch : 5 minutes. Rédige-moi un pitch en 3 parties : accroche, présentation du problème + solution, appel à l''action.\n```\n\n**Relancer des prospects :**\n```\nJ''ai rencontré [nom/type de prospect] lors de [événement] il y a [durée]. Notre échange portait sur [sujet]. Ils semblaient intéressés par [notre offre]. Rédige un email de relance chaleureux qui rouvre la conversation sans être intrusif.\n```'),

  (v_mod6, v_course_id, 'IA pour l''agriculture, la santé et l''éducation en Afrique', 'document', 2, false,
   E'# Applications IA dans les Secteurs Clés Africains\n\n## Agriculture : l''IA au service des agriculteurs africains\n\n### Les défis que l''IA peut résoudre\n- **Diagnostic des maladies des plantes** (photo → diagnostic)\n- **Prévisions météo localisées** (adapté aux micro-climats africains)\n- **Optimisation des intrants** (fertilisants, pesticides, irrigation)\n- **Prix de marché en temps réel** (éviter l''exploitation par les intermédiaires)\n- **Accès au crédit** (scoring alternatif basé sur comportement agricole)\n\n### Outils concrets\n\n**Plantix (application mobile)**\n- Photo d''une plante malade → diagnostic IA + traitement recommandé\n- **Langues :** Français disponible\n- **Disponibilité :** Afrique subsaharienne\n- **Coût :** Gratuit\n\n**Hello Tractor (mécanisation)**\n- Plateforme IA pour connecter tracteurs et agriculteurs\n- "l''Uber du tracteur" en Afrique\n- **Présent :** Nigeria, Kenya, Ghana, Zambie\n\n**Apollo Agriculture (Kenya)**\n- Crédit agricole basé sur IA\n- Analyse satellite + données météo + historique agricultural\n- Prêts jusqu''à 70 000 KES sans garantie traditionnelle\n\n**ESOKO / Farmerline (Afrique de l''Ouest)**\n- Prix de marché en temps réel par SMS\n- Conseils agronomiques personnalisés\n- **Présent :** Ghana, CI, Togo, Rwanda\n\n## Santé : l''IA pour améliorer l''accès aux soins\n\n### Défis de santé que l''IA adresse en Afrique\n- Manque de médecins spécialistes (1 médecin pour 5000 patients dans certaines zones)\n- Éloignement géographique\n- Coûts de santé élevés\n- Maladies tropicales sous-diagnostiquées\n\n### Innovations IA santé\n\n**Ada Health (application mobile)**\n- Symptômes → diagnostic probabiliste IA\n- Recommandation : automédication / médecin / urgences\n- **Langues :** Français, Swahili\n- Utilisée par plusieurs ministères de santé africains\n\n**Zipline (drones médicaux)**\n- IA pour optimiser les routes de livraison\n- Médicaments et sang livrés par drone en zones rurales\n- **Présent :** Rwanda, Ghana, Kenya, Nigeria\n- 8 millions de livraisons en Afrique\n\n**Retinal IA (diagnostic ophtalmologique)**\n- Photo de rétine → détection IA de diabète, glaucome\n- 1 infirmier peut dépister grâce à l''IA\n\n## Éducation : l''IA pour démocratiser l''accès au savoir\n\n### Applications pratiques\n\n**IBIG E-LEARNING** (vous y êtes !)\nPlateforme de formation professionnelle avec accompagnement IA SARA.\n\n**Khanmigo (Khan Academy IA)**\n- Tuteur IA personnalisé pour chaque apprenant\n- S''adapte au niveau et au rythme\n- **Gratuit pour les élèves et enseignants**\n\n**Duolingo IA**\n- Apprentissage des langues ultra-personnalisé\n- Très utilisé en Afrique pour l''anglais\n\n**Synthesis (mathématiques)**\n- IA qui adapte les exercices au niveau exact de l''élève\n- Efficace pour combler les lacunes\n\n### L''IA comme outil pédagogique pour les enseignants\n\n```\nPrompt pour enseignant :\n"Je suis professeur de [matière] en classe de [niveau] au [pays]. Mon cours porte sur [sujet]. Génère-moi :\n1. Une explication simple adaptée à des élèves de [âge] ans\n2. 3 exemples tirés du quotidien africain\n3. 5 questions de compréhension\n4. Une activité pratique de 20 minutes en groupe"\n```'),

  -- Module 7 : Éthique IA
  (v_mod7, v_course_id, 'Les biais de l''IA et leurs implications pour l''Afrique', 'document', 1, false,
   E'# Biais de l''IA et Implications Africaines\n\n## Qu''est-ce qu''un biais algorithmique ?\nUn biais algorithmique est une erreur systématique dans les résultats de l''IA qui favorise certains groupes au détriment d''autres. Il résulte souvent de données d''entraînement non représentatives ou de choix de conception qui reflètent des préjugés humains.\n\n## Les biais qui affectent particulièrement l''Afrique\n\n### 1. Le biais de représentation\n**Problème :** La plupart des IA ont été entraînées principalement sur des données occidentales (anglophones, européennes, américaines).\n\n**Conséquences pratiques :**\n- Systèmes de reconnaissance faciale moins précis sur les peaux sombres\n- Traducteurs IA moins performants pour les langues africaines\n- Modèles financiers qui pénalisent les pays africains\n- Recommandations médicales basées sur des données non africaines\n\n**Exemple documenté :** En 2018, une étude MIT a montré que les systèmes de reconnaissance faciale avaient un taux d''erreur de 34% pour les femmes à peau sombre, contre 0,8% pour les hommes à peau claire.\n\n### 2. Le biais linguistique\n**ChatGPT et les langues africaines :**\n- Excellente performance en anglais et français\n- Performances réduites en langues africaines (wolof, dioula, yoruba, swahili...)\n- Risque de perdre des nuances culturelles importantes dans les traductions\n\n**Solutions en développement :**\n- **Lelapa AI** (Afrique du Sud) : IA spécialisée dans les langues africaines\n- **Khaya IA** : LLM pour les langues africaines\n- **Initiative D4Africa** : datasets en langues africaines\n\n### 3. Le biais de crédit et d''assurance\n**Risque :** Des algorithmes de scoring financier formés sur des données occidentales peuvent désavantager systématiquement les entreprises et individus africains.\n\n**Enjeux :**\n- Refus de crédit algorithmique non justifié\n- Primes d''assurance plus élevées basées sur des corrélations discutables\n- Exclusion des populations non "bancarisées" malgré leur solvabilité réelle\n\n## Comment vous protéger des biais IA\n\n**En tant qu''utilisateur :**\n1. Ne jamais accepter aveuglément une décision algorithmique\n2. Demander toujours une explication (droit à l''explication)\n3. Signaler les erreurs et discriminations\n4. Diversifier vos sources d''information\n\n**En tant qu''entrepreneur qui déploie de l''IA :**\n1. Vérifier que vos données d''entraînement sont représentatives de votre clientèle\n2. Tester les résultats sur différents segments démographiques\n3. Inclure des experts locaux dans la conception\n4. Mettre en place un processus de révision humaine pour les décisions à fort impact\n\n## L''IA réglementaire en Afrique\n\n**Union Africaine :** Politique africaine sur l''IA adoptée en 2024\n**Côte d''Ivoire :** Cadre national de gouvernance de l''IA en développement\n**Kenya :** Politique nationale IA 2022-2027\n**Afrique du Sud :** Stratégie nationale sur l''IA\n\n**Principes émergents :**\n- Transparence des algorithmes de décision\n- Droit à l''explication\n- Protection des données personnelles (RGPD africain)\n- Responsabilité des entreprises qui déploient l''IA'),

  (v_mod7, v_course_id, 'Le futur du travail en Afrique à l''ère de l''IA', 'document', 2, false,
   E'# Futur du Travail en Afrique à l''Ère de l''IA\n\n## L''impact de l''IA sur l''emploi : réalité vs panique\n\n### Les chiffres\n- Le Forum Économique Mondial prédit que l''IA déplacera **85 millions d''emplois** mais en créera **97 millions** de nouveaux d''ici 2025\n- **Bilan net positif :** +12 millions d''emplois globalement\n- Mais : les emplois créés sont différents des emplois déplacés\n\n### Quels emplois sont menacés en Afrique ?\n\n**Risque élevé d''automatisation :**\n- Saisie de données, archivage\n- Certaines tâches comptables répétitives\n- Centre d''appel de base\n- Caissiers, guichetiers\n- Transport routier (à très long terme)\n\n**Risque modéré :**\n- Certains postes administratifs\n- Aide-comptables\n- Secrétariat\n\n**Risque faible (l''IA augmente sans remplacer) :**\n- Métiers de relation humaine (soin, éducation, conseil)\n- Métiers créatifs\n- Métiers d''artisanat\n- Managers et leaders\n- Entrepreneurs\n\n### L''opportunité africaine spécifique\nL''Afrique a 60% de la population mondiale de moins de 25 ans. Cette génération peut :\n- S''approprier l''IA nativement (pas de "désapprentissage" à faire)\n- Développer des solutions IA pour les problèmes africains\n- Exporter des services IA vers le monde (freelancing, outsourcing)\n\n## Compétences à développer pour rester pertinent\n\n### Les compétences que l''IA ne peut pas reproduire\n\n**Intelligence relationnelle :**\n- Empathie, présence humaine\n- Construction de confiance\n- Gestion des conflits complexes\n- Leadership inspirant\n\n**Jugement contextuel :**\n- Décisions éthiques complexes\n- Compréhension des nuances culturelles\n- Adaptation à des situations inédites\n\n**Créativité stratégique :**\n- Innovation de rupture\n- Vision à long terme\n- Connection d''idées disparates\n\n**Expertise spécialisée :**\n- L''IA est généraliste, vous êtes expert\n- L''IA fait les 80% basiques, vous faites les 20% critiques\n\n### Les compétences numériques prioritaires\n\n1. **Maîtrise des outils IA** (ce que vous apprenez dans cette formation)\n2. **Analyse de données** (lire et interpréter les données)\n3. **Sécurité numérique** (protéger ses actifs numériques)\n4. **Gestion de projets digitaux**\n5. **Communication digitale efficace**\n\n## L''entrepreneuriat africain augmenté par l''IA\n\n**L''IA comme équalisateur :**\nUne PME africaine avec 5 personnes et les bons outils IA peut aujourd''hui rivaliser avec une entreprise de 50 personnes qui ne les utilise pas.\n\n**Ce que l''IA donne à l''entrepreneur africain :**\n- Département marketing (contenus, publicités) → remplacé par 2h d''IA/semaine\n- Assistant juridique de base → ChatGPT + vérification avocat\n- Analyste data → outils BI + prompts analytiques\n- Développeur web → outils no-code + assistance IA\n- Traducteur → DeepL + révision humaine\n\n**L''avantage compétitif reste :**\n- Votre réseau local\n- Votre connaissance du marché africain\n- Votre réputation et vos relations\n- Votre capacité d''exécution terrain\n- Votre compréhension culturelle\n\n## Votre plan d''action pour les 12 prochains mois\n\n1. **Mois 1-2 :** Maîtriser 3 outils IA fondamentaux (ChatGPT, Canva IA, un outil d''automatisation)\n2. **Mois 3-4 :** Automatiser une tâche répétitive de votre travail actuel\n3. **Mois 5-6 :** Intégrer l''IA dans votre processus de création de contenu\n4. **Mois 7-9 :** Explorer l''IA dans votre secteur spécifique\n5. **Mois 10-12 :** Former vos collaborateurs et partager vos apprentissages\n\n**Citation finale :**\n"L''IA ne remplacera pas les humains. Mais les humains qui utilisent l''IA remplaceront ceux qui ne l''utilisent pas." — Karim Sy, fondateur Jokkolabs (Sénégal)');

